def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def intervals(size, separators):
        parts = []
        start = 0
        for pos in separators:
            if start < pos:
                parts.append((start, pos))
            start = pos + 1
        if start < size:
            parts.append((start, size))
        return parts

    row_parts = intervals(h, sep_rows)
    col_parts = intervals(w, sep_cols)

    result = []
    for r0, r1 in row_parts:
        out_row = []
        for c0, c1 in col_parts:
            cells = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            counts = {color: cells.count(color) for color in set(cells)}
            background = max(counts, key=counts.get)
            out_row.append(1 if len(cells) - counts[background] > 1 else background)
        result.append(out_row)
    return result
